/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNonNegativeNumber = require( '@stdlib/assert/is-nonnegative-number' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the position of the x axis.
* Note: x axis is vertical axis,so this setter take the width( column Number ) for position.
*
* @private
* @param {Number} value - position width( column number )
* @throws {TypeError} must be non negative number
*/
function set( value ) {
	if ( !isNonNegativeNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` non negative number is expected. Value: `%s`.', 'xAxisPos', value ) );
	}
	if ( this._axisDataObjs[ 0 ].position !== value ) {
		this._axisDataObjs[ 0 ].position = value;
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
